import rawData from 'web/lib/results-data.json'

// Generated by analysis/utils/export_web_results.R — regenerate rather than editing the JSON.

export type Prep = 'Stimulating' | 'Calming' | 'ChildChoice' | 'NoPrep'
export type ActivePrep = Exclude<Prep, 'NoPrep'>

export type PosteriorSummary = {
  mean: number
  lo95: number
  hi95: number
  lo80: number
  hi80: number
  p_positive: number
  p_rope: number
}

export type RawSummary = {n: number; mean: number | null; sd: number | null}

export type ChildResult = {
  id: number
  n_sessions: number
  first_date: string
  last_date: string
  stop_reason: string
  best_prep: string
  effects: Record<ActivePrep, PosteriorSummary>
  p_best: Record<Prep, number>
  raw: Record<Prep, RawSummary>
  sessions: {date: string; prep: string; engagement: number}[]
}

export type ResultsData = {
  generated: string
  rope: number
  n_children: number
  n_sessions: number
  first_date: string
  last_date: string
  n_teachers: number
  group: {
    intercept: PosteriorSummary
    sigma: PosteriorSummary
    sd_child_intercept: PosteriorSummary
    effects: Record<ActivePrep, PosteriorSummary>
    child_sd: Record<ActivePrep, PosteriorSummary>
    raw: Record<Prep, RawSummary>
  }
  stop_counts: Record<string, number>
  quality: {
    share_rated_over_1h: number
    share_rated_over_3h: number
    share_identical_ratings: number
    share_under_12_sessions: number
  }
  children: ChildResult[]
}

export const RESULTS = rawData as ResultsData

export const ACTIVE_PREPS: ActivePrep[] = ['Stimulating', 'Calming', 'ChildChoice']
export const ALL_PREPS: Prep[] = [...ACTIVE_PREPS, 'NoPrep']

// Colours match the condition cards (a = Stimulating, b = Calming, c = Child-Led, d = Control)
export const PREP_META: Record<Prep, {label: string; color: string}> = {
  Stimulating: {label: 'Stimulating', color: '#c4706e'},
  Calming: {label: 'Calming', color: '#4a8fa8'},
  ChildChoice: {label: 'Child-Led', color: '#8b7fb8'},
  NoPrep: {label: 'No Prep', color: '#c49a72'},
}

export const pct = (x: number) => `${Math.round(x * 100)}%`

export const signed = (x: number, digits = 2) =>
  `${x >= 0 ? '+' : '−'}${Math.abs(x).toFixed(digits)}`
